    interior = [(r, c) for r in range(h) for c in range(w)
                if grid[r][c] not in (bg,)]
    edge_colors = set()
    for r in range(h):
        if grid[r][0] != bg:
            edge_colors.add(grid[r][0])
        if grid[r][w-1] != bg:
            edge_colors.add(grid[r][w-1])
    for c in range(w):
        if grid[0][c] != bg:
            edge_colors.add(grid[0][c])
        if grid[h-1][c] != bg:
            edge_colors.add(grid[h-1][c])
    marker_color = next((grid[r][c] for r, c in interior
                         if grid[r][c] not in edge_colors), None)
    if marker_color is None:
